     6→export type ConversationWithMeta = {
     7→  id: string;
     8→  updated_at: string;
     9→  otherUser: {
    10→    id: string;
    11→    full_name: string;
    12→  };
    13→  lastMessage: {
    14→    body: string;
    15→    created_at: string;
    16→    sender_id: string;
    17→  } | null;
    18→  unreadCount: number;
    19→};
