    30→export async function getConversations(userId: string): Promise<ConversationWithMeta[]> {
    31→  const supabase = await createServerSupabaseClient();
    32→  const adminClient = createAdminClient();
    33→
    34→  // Get all conversation IDs the user is in
    35→  const { data: participantRows, error: pErr } = await supabase
    36→    .schema("messaging")
    37→    .from("conversation_participants")
    38→    .select("conversation_id")
    39→    .eq("user_id", userId);
    40→
    41→  if (pErr) console.error("[getConversations] participantRows error:", pErr);
    42→  if (pErr || !participantRows?.length) return [];
    43→
    44→  const conversationIds = participantRows.map((r) => r.conversation_id);
    45→
    46→  // Get conversations
    47→  const { data: convos, error: cErr } = await supabase
    48→    .schema("messaging")
    49→    .from("conversations")
    50→    .select("id, updated_at")
    51→    .in("id", conversationIds)
    52→    .order("updated_at", { ascending: false });
    53→
    54→  if (cErr) console.error("[getConversations] convos error:", cErr);
    55→  if (cErr || !convos?.length) return [];
    56→
    57→  // For each conversation, get the other participant's user_id
    58→  const { data: allParticipants } = await supabase
    59→    .schema("messaging")
    60→    .from("conversation_participants")
    61→    .select("conversation_id, user_id")
    62→    .in("conversation_id", conversationIds);
    63→
    64→  // Get the other user ids (not current user)
    65→  const otherUserIds = [
    66→    ...new Set(
    67→      (allParticipants ?? [])
    68→        .filter((p) => p.user_id !== userId)
    69→        .map((p) => p.user_id)
    70→    ),
    71→  ];
    72→
    73→  // Fetch full_name from admin.users for those ids
    74→  const { data: adminUsers } = await adminClient
    75→    .schema("admin")
    76→    .from("users")
    77→    .select("id, full_name")
    78→    .in("id", otherUserIds);
    79→
    80→  const userMap = new Map((adminUsers ?? []).map((u) => [u.id, u]));
    81→
    82→  // Get latest message + unread count for each conversation
    83→  const result: ConversationWithMeta[] = await Promise.all(
    84→    convos.map(async (convo) => {
    85→      const otherParticipant = (allParticipants ?? []).find(
    86→        (p) => p.conversation_id === convo.id && p.user_id !== userId
    87→      );
    88→      const otherUser = otherParticipant
    89→        ? userMap.get(otherParticipant.user_id)
    90→        : null;
    91→
    92→      const { data: messages } = await supabase
    93→        .schema("messaging")
    94→        .from("messages")
    95→        .select("id, body, created_at, sender_id, read_at")
    96→        .eq("conversation_id", convo.id)
    97→        .order("created_at", { ascending: false })
    98→        .limit(1);
    99→
   100→      const lastMessage = messages?.[0] ?? null;
   101→
   102→      const { count: unreadCount } = await supabase
   103→        .schema("messaging")
   104→        .from("messages")
   105→        .select("id", { count: "exact", head: true })
   106→        .eq("conversation_id", convo.id)
   107→        .neq("sender_id", userId)
   108→        .is("read_at", null);
   109→
   110→      return {
   111→        id: convo.id,
   112→        updated_at: convo.updated_at,
   113→        otherUser: {
   114→          id: otherUser?.id ?? otherParticipant?.user_id ?? "",
   115→          full_name: otherUser?.full_name ?? "Unknown",
   116→        },
   117→        lastMessage: lastMessage
   118→          ? {
   119→              body: lastMessage.body,
   120→              created_at: lastMessage.created_at,
   121→              sender_id: lastMessage.sender_id,
   122→            }
   123→          : null,
   124→        unreadCount: unreadCount ?? 0,
   125→      };
   126→    })
   127→  );
   128→
   129→  return result;
   130→}
