   132→export async function getMessages(conversationId: string): Promise<MessageRow[]> {
   133→  const supabase = await createServerSupabaseClient();
   134→
   135→  const { data, error } = await supabase
   136→    .schema("messaging")
   137→    .from("messages")
   138→    .select("id, conversation_id, sender_id, body, created_at, read_at")
   139→    .eq("conversation_id", conversationId)
   140→    .order("created_at", { ascending: true });
   141→
   142→  if (error) return [];
   143→  return data ?? [];
